#include "pal_udp.h"

#include <string.h>
#include "lwip/sockets.h"
#include "lwip/netdb.h"
#include "esp_log.h"

static const char *TAG = "pal_udp";

pal_udp_socket_t pal_udp_create(void) {
    int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sock < 0) {
        ESP_LOGE(TAG, "Failed to create socket: errno %d", errno);
        return PAL_UDP_INVALID_SOCKET;
    }
    return (pal_udp_socket_t)sock;
}

int pal_udp_bind(pal_udp_socket_t sock, uint16_t port) {
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        ESP_LOGE(TAG, "Bind failed on port %u: errno %d", port, errno);
        return -1;
    }
    return 0;
}

int pal_udp_sendto(pal_udp_socket_t sock, const pal_udp_endpoint_t *dest,
                   const void *data, size_t len) {
    if (!dest || !data) return -1;

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(dest->port);
    inet_aton(dest->addr, &addr.sin_addr);

    int sent = sendto(sock, data, len, 0, (struct sockaddr *)&addr, sizeof(addr));
    if (sent < 0) {
        ESP_LOGE(TAG, "sendto failed: errno %d", errno);
    }
    return sent;
}

int pal_udp_recvfrom(pal_udp_socket_t sock, pal_udp_endpoint_t *src,
                     void *buf, size_t buf_len, uint32_t timeout_ms) {
    if (!buf) return -1;

    if (timeout_ms > 0 && timeout_ms != UINT32_MAX) {
        struct timeval tv;
        tv.tv_sec = timeout_ms / 1000;
        tv.tv_usec = (timeout_ms % 1000) * 1000;
        setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    } else if (timeout_ms == 0) {
        int flags = fcntl(sock, F_GETFL, 0);
        fcntl(sock, F_SETFL, flags | O_NONBLOCK);
    }

    struct sockaddr_in from_addr = {0};
    socklen_t from_len = sizeof(from_addr);

    int n = recvfrom(sock, buf, buf_len, 0, (struct sockaddr *)&from_addr, &from_len);

    if (timeout_ms == 0) {
        int flags = fcntl(sock, F_GETFL, 0);
        fcntl(sock, F_SETFL, flags & ~O_NONBLOCK);
    }

    if (n < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) return 0;
        return -1;
    }

    if (src) {
        inet_ntoa_r(from_addr.sin_addr, src->addr, sizeof(src->addr));
        src->port = ntohs(from_addr.sin_port);
    }
    return n;
}

void pal_udp_close(pal_udp_socket_t sock) {
    if (sock != PAL_UDP_INVALID_SOCKET) {
        close(sock);
    }
}

int pal_udp_set_timeout(pal_udp_socket_t sock, uint32_t timeout_ms) {
    struct timeval tv;
    tv.tv_sec = timeout_ms / 1000;
    tv.tv_usec = (timeout_ms % 1000) * 1000;
    return setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv)) == 0 ? 0 : -1;
}

int pal_udp_set_broadcast(pal_udp_socket_t sock, bool enable) {
    int val = enable ? 1 : 0;
    return setsockopt(sock, SOL_SOCKET, SO_BROADCAST, &val, sizeof(val)) == 0 ? 0 : -1;
}